/* Tbm02Mapper.selectSessionCd */
SELECT CONCAT('T', DATE_FORMAT(CURDATE(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL('__GLOBAL__', 'TBM_SESSION_CD'))
FROM DUAL

mapper.sql:
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.DEL_YN = 'N'
  /* 스코프 필터: master/safe(companyWide=true)는 회사 전체, 그 외는 자기 사업장만 */

    AND A.SITE_CD = #{scopeSiteCd}


    AND A.SITE_CD = #{siteCd}


    AND A.STATUS_CD = #{statusCd}


    AND A.MANAGER_USER_CD = #{managerUserCd}


    AND A.TITLE LIKE CONCAT('%', #{searchKeyword}, '%')


    AND DATE(A.INSERT_DATE) >= #{startDate}


    AND DATE(A.INSERT_DATE) <= #{endDate}

WHERE S.DEL_YN = 'N'
  /* 개설사 세션은 기존 목록 소관 — 여기서는 타사 세션만 */
  AND S.CMPNY_CD <> #{gvCmpnyCd}
  /* 스코프 = 인가: 내 회사가 유효(DEL_YN='N')하게 지정받은 세션만 */
  AND EXISTS (
        SELECT 1
        FROM TB_TBM_SESSION_SHARE SH
        WHERE SH.SESSION_CD = S.SESSION_CD
          AND SH.SHARE_CMPNY_CD = #{gvCmpnyCd}
          AND SH.DEL_YN = 'N'
      )

    AND S.STATUS_CD = #{statusCd}


    AND S.TITLE LIKE CONCAT('%', #{searchKeyword}, '%')

