/* Tbm02Mapper.insertSession */
INSERT INTO TB_TBM_SESSION (
	SESSION_CD
	, CMPNY_CD
	, SITE_CD
	, EDU_TYPE_CD
	, TITLE
	, CONTENT_BODY
	, CONTENT_FORMAT_CD
	, STATUS_CD
	, ENTRY_PWD
	, EXIT_PWD
	, MANAGER_USER_CD
	, MANAGER_GPS_LAT
	, MANAGER_GPS_LON
	, GPS_VERIFY_TYPE_CD
	, GPS_VERIFY_RADIUS_M
	, EDU_MINUTES
	, GPS_MANUAL_CONFIRM_YN
	, OPENED_AT
	, DEL_YN
	, INSERT_NO
	, INSERT_DATE
	, UPDATE_NO
	, UPDATE_DATE
) VALUES (
	#{sessionCd}
	, #{gvCmpnyCd}
	, #{siteCd}
	, 'TBM'
	, #{title}
	, #{contentBody}
	, 'RICH_HTML'
	, #{statusCd}
	, #{entryPwd}
	, #{exitPwd}
	, #{managerUserCd}
	, #{managerGpsLat}
	, #{managerGpsLon}
	, IFNULL(#{gpsVerifyTypeCd}, 'AUTO')
	, IFNULL(#{gpsVerifyRadiusM}, 100)
	, #{eduMinutes}
	, #{gpsManualConfirmYn}

		, NOW()
		, NULL

	, 'N'
	, #{gvUserCd}
	, NOW()
	, #{gvUserCd}
	, NOW()
)

mapper.update:
/* Tbm02Mapper.updateSession */
UPDATE TB_TBM_SESSION
SET
	TITLE					= #{title}
	, CONTENT_BODY			= #{contentBody}
	, GPS_VERIFY_TYPE_CD	= IFNULL(#{gpsVerifyTypeCd}, GPS_VERIFY_TYPE_CD)
	, GPS_VERIFY_RADIUS_M	= IFNULL(#{gpsVerifyRadiusM}, GPS_VERIFY_RADIUS_M)
	/* 교육 인정시간(분). 미전송(NULL) 시 기존값 보존 */
	, EDU_MINUTES			= IFNULL(#{eduMinutes}, EDU_MINUTES)
	, MANAGER_GPS_LAT		= #{managerGpsLat}
	, MANAGER_GPS_LON		= #{managerGpsLon}
	, GPS_MANUAL_CONFIRM_YN	= #{gpsManualConfirmYn}
	, UPDATE_NO				= #{gvUserCd}
	, UPDATE_DATE			= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD IN ('DRAFT', 'OPENED')

