/* Tbm02Mapper.cancelSession */
UPDATE TB_TBM_SESSION
SET
	STATUS_CD		= 'CANCELLED'
	, CANCELLED_AT	= NOW()
	, CANCEL_REASON	= #{cancelReason}
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD IN ('DRAFT', 'OPENED')

/* Tbm02Mapper.prepareSession */
UPDATE TB_TBM_SESSION
SET
	STATUS_CD				= 'OPENED'
	/* §X-2(Q5-A): 교육준비는 경량 전이. TITLE/CONTENT_BODY 는 개설/수정에서 확정된 DB값을
	   유지하며 prepare 에서 덮어쓰지 않는다(FE 미전송 값으로 인한 손실 방지). */
	, ENTRY_PWD				= #{entryPwd}
	, MANAGER_GPS_LAT		= #{managerGpsLat}
	, MANAGER_GPS_LON		= #{managerGpsLon}
	, GPS_VERIFY_TYPE_CD	= IFNULL(#{gpsVerifyTypeCd}, GPS_VERIFY_TYPE_CD)
	, GPS_VERIFY_RADIUS_M	= IFNULL(#{gpsVerifyRadiusM}, GPS_VERIFY_RADIUS_M)
	, GPS_MANUAL_CONFIRM_YN	= #{gpsManualConfirmYn}
	, OPENED_AT				= IFNULL(OPENED_AT, NOW())
	, PREP_START_AT			= NOW()
	, UPDATE_NO				= #{gvUserCd}
	, UPDATE_DATE			= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'DRAFT'

/* Tbm02Mapper.updateEntryPwd */
UPDATE TB_TBM_SESSION
SET
	ENTRY_PWD		= #{pwd}
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'OPENED'

/* Tbm02Mapper.updateExitPwd */
UPDATE TB_TBM_SESSION
SET
	EXIT_PWD		= #{pwd}
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'COMPLETED'

/* Tbm02Mapper.startSession */
UPDATE TB_TBM_SESSION
SET
	STATUS_CD		= 'IN_PROGRESS'
	, STARTED_AT	= NOW()
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'OPENED'

/* Tbm02Mapper.extendPrep */
UPDATE TB_TBM_SESSION
SET
	PREP_START_AT	= NOW()
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'OPENED'
  AND PREP_START_AT IS NOT NULL
  AND PREP_START_AT > (NOW() - INTERVAL 15 MINUTE)

/* Tbm02Mapper.completeSession */
UPDATE TB_TBM_SESSION
SET
	STATUS_CD		= 'COMPLETED'
	, ENDED_AT		= NOW()
	, EXIT_PWD		= #{exitPwd}
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'IN_PROGRESS'

mapper.select:
/* Tbm02Mapper.selectContentOptions */ SELECT A.MTRL_CD AS mtrlCd , A.TITLE AS title , A.MTRL_TYPE AS mtrlType , BD.BAIM_VAL_D_NM AS mtrlTypeNm , A.SITE_CD AS siteCd , CASE WHEN A.SITE_CD IS NULL THEN 'Y' ELSE 'N' END AS isCommonContent , ( SELECT COUNT(I.MTRL_ITEM_CD) FROM TB_TBM_EDU_MTRL_ITEM I /* 테넌트 격리: MTRL_CD 는 회사별 채번이라 전역 유일하지 않다. 항목의 CMPNY_CD 로 함께 좁힌다. */ WHERE I.CMPNY_CD = A.CMPNY_CD AND I.MTRL_CD = A.MTRL_CD AND I.USE_YN = 'Y' ) AS itemCnt FROM TB_TBM_EDU_MTRL A LEFT OUTER JOIN TB_BAIM_VAL_D BD ON ( BD.CMPNY_CD = A.CMPNY_CD AND BD.BAIM_VAL_CD = 'COM003' AND BD.BAIM_VAL_D_CD = A.MTRL_TYPE AND BD.USE_YN = 'Y' ) WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.USE_YN = 'Y' /* 스코프 필터: master/safe(companyWide=true)는 회사 전체, 그 외는 자기사업장+회사공통 */
AND (A.SITE_CD IS NULL OR A.SITE_CD = #{scopeSiteCd})
AND A.SITE_CD IS NULL
/* 세션 콘텐츠 선택: 해당 사업장 자료 + 회사공통(SITE_CD IS NULL) 자료 포함 */ AND (A.SITE_CD IS NULL OR A.SITE_CD = #{siteCd})
AND A.TITLE LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.SITE_CD IS NOT NULL, A.TITLE

/* Tbm02Mapper.selectRiskOptions */ SELECT A.SITE_CD AS siteCd , A.PROCESS_CD AS processCd , C.BAIM_VAL_D_NM AS processNm , A.RISK_TYPE_CD AS riskTypeCd , D.RISK_TYPE_NM AS riskTypeNm , A.HAZARD_CD AS hazardCd , CASE WHEN A.HAZARD_CD = 'self' THEN A.ASSESSMENT_DESC ELSE E.HAZARD_NM END AS hazardNm , A.ASSESSMENT_CD AS assessmentCd , A.ASSESSMENT_STATUS AS assessmentStatus , B.SYST_VAL_D_NM AS assessmentStatusNm /* 6.3(T6-13): 위험성평가 선택 팝업 컬럼 — 평가요청일/평가요청자 */ , DATE_FORMAT(A.INIT_ASSESS_DATE, '%Y-%m-%d') AS initAssessDate , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'USER_NM', A.INIT_ASSESSOR_ID, NULL) AS initAssessorNm FROM TB_RISK_ASSESSMENT A LEFT OUTER JOIN ( SELECT G.SYST_VAL_D_CD, G.SYST_VAL_D_NM FROM TB_SYST_VAL_D G WHERE G.SYST_VAL_CD = 'SYS011' AND G.USE_YN = 'Y' ) B ON ( A.ASSESSMENT_STATUS = B.SYST_VAL_D_CD ) LEFT OUTER JOIN TB_BAIM_VAL_D C ON ( C.CMPNY_CD = A.CMPNY_CD AND C.BAIM_VAL_CD = 'COM002' AND C.BAIM_VAL_D_CD = A.PROCESS_CD AND C.USE_YN = 'Y' ) LEFT OUTER JOIN TB_RISK_TYPE D ON ( A.CMPNY_CD = D.CMPNY_CD AND A.RISK_TYPE_CD = D.RISK_TYPE_CD ) LEFT OUTER JOIN TB_RISK_SITE_HAZARD E ON ( A.CMPNY_CD = E.CMPNY_CD AND A.RISK_TYPE_CD = E.RISK_TYPE_CD AND A.HAZARD_CD = E.HAZARD_CD ) WHERE A.CMPNY_CD = #{gvCmpnyCd} /* 스코프 필터: master/safe는 회사 전체, 그 외는 자기 사업장만 */
AND A.SITE_CD = #{scopeSiteCd}
AND A.SITE_CD = #{siteCd}
AND A.PROCESS_CD = #{processCd}
AND A.RISK_TYPE_CD = #{riskTypeCd}
AND ( CASE WHEN A.HAZARD_CD = 'self' THEN A.ASSESSMENT_DESC ELSE E.HAZARD_NM END ) LIKE CONCAT('%', #{hazardDesc}, '%')
AND FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'USER_NM', A.INIT_ASSESSOR_ID, NULL) LIKE CONCAT('%', #{initAssessorNm}, '%')
AND DATE(A.INIT_ASSESS_DATE) = #{initAssessDate}
ORDER BY A.SITE_CD, A.PROCESS_CD, A.RISK_TYPE_CD, A.HAZARD_CD

/* Tbm02Mapper.selectRegularCandidates */ SELECT U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.SITE_CD AS siteCd , ST.SITE_NM AS siteNm , NULL AS mblNoLast4 , CASE WHEN EXISTS ( SELECT 1 FROM TB_TBM_ATTENDANCE AT WHERE AT.CMPNY_CD = U.CMPNY_CD AND AT.SESSION_CD = #{sessionCd} AND AT.USER_TYPE_CD = 'REGULAR' AND AT.USER_CD = U.USER_CD AND AT.DEL_YN = 'N' ) THEN 1 ELSE 0 END AS alreadyEntered
, U.CMPNY_CD AS cmpnyCd FROM TB_USER U LEFT OUTER JOIN TB_SITE ST ON ( U.CMPNY_CD = ST.CMPNY_CD AND U.SITE_CD = ST.SITE_CD )
WHERE U.CMPNY_CD IN
#{tc}
AND U.SITE_CD = #{siteCd}
AND U.USE_YN = 'Y' AND U.ACCOUNT_STATUS = '01' /* T6-06: 당일 출근자만 노출(자사=세션 사업장 기준, 타사=회사 단위 — 사업장 조건 제거, plan D6) */ AND EXISTS ( SELECT 1 FROM TB_USER_ATTD_MGMT WA WHERE WA.CMPNY_CD = U.CMPNY_CD
AND WA.SITE_CD = #{siteCd}
AND WA.USER_CD = U.USER_CD AND WA.DEL_YN = 'N' AND WA.CHECK_IN_TIME IS NOT NULL AND WA.WORK_YMD = DATE_FORMAT(NOW(), '%Y%m%d') )
AND ( U.USER_NM LIKE CONCAT('%', #{keyword}, '%') OR U.USER_ID LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY U.USER_NM, U.USER_CD LIMIT 100

/* Tbm02Mapper.selectDailyCandidates */ SELECT DU.USER_CD AS userCd , DU.USER_ID AS userId , DU.USER_NM AS userNm , DU.SITE_CD AS siteCd , ST.SITE_NM AS siteNm , DU.MBL_NO_LAST4 AS mblNoLast4 , CASE WHEN EXISTS ( SELECT 1 FROM TB_TBM_ATTENDANCE AT WHERE AT.CMPNY_CD = DU.CMPNY_CD AND AT.SESSION_CD = #{sessionCd} AND AT.USER_TYPE_CD = 'DAILY' AND AT.USER_CD = DU.USER_CD AND AT.DEL_YN = 'N' ) THEN 1 ELSE 0 END AS alreadyEntered
, DU.CMPNY_CD AS cmpnyCd FROM TB_DAILY_USER DU LEFT OUTER JOIN TB_SITE ST ON ( DU.CMPNY_CD = ST.CMPNY_CD AND DU.SITE_CD = ST.SITE_CD )
WHERE DU.CMPNY_CD IN
#{tc}
AND DU.SITE_CD = #{siteCd}
AND DU.USE_YN = 'Y' AND DU.ACCOUNT_STATUS = '01' AND DU.WITHDRAWAL_DATE IS NULL AND DU.WORK_EXPIRE_DATE >= DATE_FORMAT(NOW(), '%Y%m%d')
AND EXISTS ( SELECT 1 FROM TB_USER_ATTD_MGMT WA WHERE WA.CMPNY_CD = DU.CMPNY_CD AND WA.USER_CD = DU.USER_CD AND WA.DEL_YN = 'N' AND WA.CHECK_IN_TIME IS NOT NULL AND WA.WORK_YMD = DATE_FORMAT(NOW(), '%Y%m%d') )
AND ( DU.USER_NM LIKE CONCAT('%', #{keyword}, '%') OR DU.USER_ID LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY DU.USER_NM, DU.USER_CD LIMIT 100

/* Tbm02Mapper.selectEntryTargetCmpnyCds */


		SELECT DU.CMPNY_CD
		FROM TB_DAILY_USER DU
		WHERE DU.CMPNY_CD IN

		    #{tc}


		    AND DU.SITE_CD = #{siteCd}

		  AND DU.USER_CD = #{userCd}
		  AND DU.USE_YN = 'Y'
		  AND DU.ACCOUNT_STATUS = '01'
		  AND DU.WITHDRAWAL_DATE IS NULL
		  AND DU.WORK_EXPIRE_DATE >= DATE_FORMAT(NOW(), '%Y%m%d')


		SELECT U.CMPNY_CD
		FROM TB_USER U
		WHERE U.CMPNY_CD IN

		    #{tc}


		    AND U.SITE_CD = #{siteCd}

		  AND U.USER_CD = #{userCd}
		  AND U.USE_YN = 'Y'
		  AND U.ACCOUNT_STATUS = '01'

/* Tbm02Mapper.selectAttendanceSlot */
SELECT
	AT.ATTENDANCE_CD	AS attendanceCd
	, AT.DEL_YN			AS delYn
FROM TB_TBM_ATTENDANCE AT
WHERE AT.CMPNY_CD = #{targetCmpnyCd}
  AND AT.SESSION_CD = #{sessionCd}
  AND AT.USER_TYPE_CD = #{userTypeCd}
  AND AT.USER_CD = #{userCd}
LIMIT 1

mapper.insert:
/* Tbm02Mapper.insertManagerEntry */
INSERT INTO TB_TBM_ATTENDANCE (
	  ATTENDANCE_CD
	, CMPNY_CD
	, SESSION_CD
	, USER_TYPE_CD
	, USER_CD
	, ENTRY_TYPE_CD
	, ENTRY_BY_MANAGER_USER_CD
	, ENTRY_AT
	, DEL_YN
	, INSERT_NO
	, INSERT_DATE
	, UPDATE_NO
	, UPDATE_DATE
)
VALUES (

	  CONCAT('A', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL('__GLOBAL__', 'TBM_ATTENDANCE_CD'))
	, #{targetCmpnyCd}
	, #{sessionCd}
	, #{userTypeCd}
	, #{userCd}
	, 'MANAGER_DIRECT'
	, #{managerUserCd}
	, NOW()
	, 'N'
	, #{managerUserCd}
	, NOW()
	, #{managerUserCd}
	, NOW()
)

mapper.select:
/* Tbm02Mapper.selectSessionAttendances */ SELECT AT.ATTENDANCE_CD AS attendanceCd , AT.USER_TYPE_CD AS userTypeCd , CASE WHEN AT.USER_TYPE_CD = 'REGULAR' THEN RU.USER_NM ELSE DU.USER_NM END AS userNm , DU.MBL_NO_LAST4 AS mblNoLast4 , AT.ENTRY_TYPE_CD AS entryTypeCd , DATE_FORMAT(AT.ENTRY_AT, '%Y-%m-%d %H:%i') AS entryAt , AT.ENTRY_DISTANCE_M AS entryDistanceM , CASE WHEN AT.EXIT_AT IS NOT NULL THEN 1 ELSE 0 END AS exited
, AT.CMPNY_CD AS cmpnyCd FROM TB_TBM_ATTENDANCE AT LEFT OUTER JOIN TB_USER RU ON ( AT.USER_TYPE_CD = 'REGULAR' AND AT.CMPNY_CD = RU.CMPNY_CD AND AT.USER_CD = RU.USER_CD ) LEFT OUTER JOIN TB_DAILY_USER DU ON ( AT.USER_TYPE_CD = 'DAILY' AND AT.CMPNY_CD = DU.CMPNY_CD AND AT.USER_CD = DU.USER_CD )
WHERE AT.SESSION_CD = #{sessionCd} AND AT.DEL_YN = 'N' ORDER BY AT.ENTRY_AT IS NULL, AT.ENTRY_AT, AT.ATTENDANCE_CD

mapper.update:
/* Tbm02Mapper.ejectAttendance */
UPDATE TB_TBM_ATTENDANCE
SET
	  DEL_YN				= 'Y'
	, EXIT_FORCED_REASON	= #{reason}
	, UPDATE_NO				= #{gvUserCd}
	, UPDATE_DATE			= NOW()

WHERE SESSION_CD = #{sessionCd}
  AND ATTENDANCE_CD = #{attendanceCd}
  AND DEL_YN = 'N'
  AND EXISTS (
      SELECT 1
      FROM TB_TBM_SESSION S
      WHERE S.SESSION_CD = #{sessionCd}
        AND S.CMPNY_CD = #{gvCmpnyCd}
        AND S.DEL_YN = 'N'
  )
